import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import toast from "react-hot-toast";

export default function Editor({ sessionId, resumeData, onResumeUpdate, onBack }) {
  const [tab, setTab] = useState("preview"); // preview | latex
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      content:
        "Hi! I'm your resume editor. Your tailored resume is ready. You can ask me to make any changes — shorten the summary, add keywords, rewrite experience bullets, change the tone, anything. What would you like to fix?",
    },
  ]);
  const [input, setInput] = useState("");
  const [chatLoading, setChatLoading] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  async function handleSend() {
    if (!input.trim() || chatLoading) return;
    const userMsg = input.trim();
    setInput("");
    setMessages((prev) => [...prev, { role: "user", content: userMsg }]);
    setChatLoading(true);

    try {
      const res = await axios.post("/api/chat", {
        session_id: sessionId,
        message: userMsg,
      });
      setMessages((prev) => [
        ...prev,
        { role: "assistant", content: res.data.response },
      ]);
      if (res.data.updated_resume) {
        onResumeUpdate({
          ...resumeData,
          tailored_resume: res.data.updated_resume,
          latex_code: res.data.updated_latex,
        });
        setMessages((prev) => [
          ...prev,
          { role: "system", content: "✅ Resume updated successfully" },
        ]);
      }
    } catch (err) {
      toast.error(err.response?.data?.detail || "Chat failed");
      setMessages((prev) => [
        ...prev,
        { role: "assistant", content: "Sorry, something went wrong. Please try again." },
      ]);
    } finally {
      setChatLoading(false);
    }
  }

  function handleKeyDown(e) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  }

  async function downloadPDF() {
    try {
      const formData = new FormData();
      formData.append("session_id", sessionId);
      const res = await axios.post("/api/download/pdf", formData, { responseType: "blob" });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement("a");
      a.href = url; a.download = "tailored_resume.pdf"; a.click();
      URL.revokeObjectURL(url);
      toast.success("PDF downloaded!");
    } catch (err) {
      toast.error("PDF download failed.");
    }
  }

  function downloadLatex() {
    const blob = new Blob([resumeData.latex_code], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "resume.tex"; a.click();
    URL.revokeObjectURL(url);
    toast.success("LaTeX file downloaded!");
  }

  const resume = resumeData.tailored_resume;
  const addedKeywords     = resumeData.added_keywords     || [];
  const newScore          = resumeData.new_ats_score;
  const originalScore     = resumeData.original_ats_score;
  const improvement       = resumeData.score_improvement  ?? (newScore - originalScore);
  const hasKeywordReport  = addedKeywords.length > 0 || newScore != null;

  return (
    <div>
      <div className="flex items-center gap-3 mb-4">
        <button className="btn btn-ghost btn-sm" onClick={onBack}>← Back</button>
        <div>
          <h1 className="page-title" style={{ fontSize: 28, marginBottom: 0 }}>Resume Editor</h1>
          <p className="page-subtitle" style={{ marginBottom: 0 }}>
            Review your tailored resume and refine it with the AI chatbot
          </p>
        </div>
      </div>

      {/* ── Keyword Injection Report ─────────────────────────────────────── */}
      {hasKeywordReport && (
        <div style={{
          background: "linear-gradient(135deg, rgba(124,106,255,0.08), rgba(167,139,250,0.06))",
          border: "1px solid rgba(124,106,255,0.3)",
          borderRadius: "var(--radius)",
          padding: "20px 24px",
          marginBottom: 20,
          display: "flex",
          gap: 32,
          flexWrap: "wrap",
          alignItems: "flex-start",
        }}>
          {/* Score comparison */}
          <div style={{ flexShrink: 0 }}>
            <p style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.08em", color: "var(--text3)", marginBottom: 10, textTransform: "uppercase" }}>
              ATS Score
            </p>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontSize: 28, fontWeight: 800, color: "var(--text2)", lineHeight: 1 }}>
                  {originalScore}
                </div>
                <div style={{ fontSize: 10, color: "var(--text3)", marginTop: 2 }}>Before</div>
              </div>
              <div style={{ fontSize: 20, color: "var(--text3)" }}>→</div>
              <div style={{ textAlign: "center" }}>
                <div style={{
                  fontSize: 28, fontWeight: 800, lineHeight: 1,
                  color: newScore >= 70 ? "var(--green)" : newScore >= 45 ? "#eab308" : "var(--red)"
                }}>
                  {newScore}
                </div>
                <div style={{ fontSize: 10, color: "var(--text3)", marginTop: 2 }}>After</div>
              </div>
              {improvement > 0 && (
                <div style={{
                  background: "rgba(34,197,94,0.15)",
                  border: "1px solid rgba(34,197,94,0.3)",
                  borderRadius: 8,
                  padding: "4px 10px",
                  fontSize: 13,
                  fontWeight: 700,
                  color: "var(--green)",
                  marginLeft: 4,
                }}>
                  +{improvement}
                </div>
              )}
            </div>
          </div>

          {/* Divider */}
          <div style={{ width: 1, background: "var(--border)", alignSelf: "stretch" }} />

          {/* Added keywords */}
          <div style={{ flex: 1, minWidth: 240 }}>
            <p style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.08em", color: "var(--text3)", marginBottom: 10, textTransform: "uppercase" }}>
              {addedKeywords.length} Keyword{addedKeywords.length !== 1 ? "s" : ""} Injected
            </p>
            {addedKeywords.length > 0 ? (
              <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                {addedKeywords.map((kw) => (
                  <span key={kw} style={{
                    background: "rgba(124,106,255,0.15)",
                    border: "1px solid rgba(124,106,255,0.35)",
                    borderRadius: 6,
                    padding: "3px 10px",
                    fontSize: 12,
                    fontWeight: 600,
                    color: "var(--accent2)",
                    display: "flex",
                    alignItems: "center",
                    gap: 5,
                  }}>
                    <span style={{ color: "var(--green)", fontSize: 10 }}>✦</span>
                    {kw}
                  </span>
                ))}
              </div>
            ) : (
              <p style={{ fontSize: 13, color: "var(--text3)" }}>
                Your resume already covered the key terms well.
              </p>
            )}
          </div>
        </div>
      )}

      {/* ── Main editor layout ───────────────────────────────────────────── */}
      <div className="editor-layout">
        {/* Resume Preview Panel */}
        <div className="resume-preview">
          <div className="resume-tabs">
            <button
              className={`resume-tab ${tab === "preview" ? "active" : ""}`}
              onClick={() => setTab("preview")}
            >
              Preview
            </button>
            <button
              className={`resume-tab ${tab === "latex" ? "active" : ""}`}
              onClick={() => setTab("latex")}
            >
              LaTeX Code
            </button>
          </div>

          <div className="resume-content">
            {tab === "preview" ? (
              <ResumePreview resume={resume} addedKeywords={addedKeywords} />
            ) : (
              <pre className="latex-code">{resumeData.latex_code}</pre>
            )}
          </div>

          <div className="download-actions">
            <button className="btn btn-primary" onClick={downloadPDF}>⬇ Download PDF</button>
            <button className="btn btn-secondary" onClick={downloadLatex}>⬇ Download .tex</button>
          </div>
        </div>

        {/* Chat Panel */}
        <div className="chat-panel">
          <div className="chat-header">
            <div className="chat-header-dot" />
            <span style={{ fontWeight: 600, fontSize: 14 }}>AI Resume Editor</span>
            <span className="badge badge-purple" style={{ marginLeft: "auto", fontSize: 11 }}>
              Sliding window active
            </span>
          </div>

          <div className="chat-messages">
            {messages.map((msg, i) => (
              <div key={i} className={`chat-msg ${msg.role}`}>
                {msg.content}
              </div>
            ))}
            {chatLoading && (
              <div className="chat-msg assistant" style={{ opacity: 0.6 }}>
                <span className="spinner" style={{ width: 12, height: 12, borderWidth: 2, display: "inline-block" }} />
                {" "}Editing...
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div style={{ padding: "8px 16px", borderTop: "1px solid var(--border)" }}>
            <p style={{ fontSize: 11, color: "var(--text3)", marginBottom: 6 }}>Quick edits:</p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
              {[
                "Shorten the summary",
                "Add more keywords",
                "Make bullets more impactful",
                "Improve ATS score",
              ].map((prompt) => (
                <button
                  key={prompt}
                  className="btn btn-secondary btn-sm"
                  style={{ fontSize: 11, padding: "4px 10px" }}
                  onClick={() => setInput(prompt)}
                >
                  {prompt}
                </button>
              ))}
            </div>
          </div>

          <div className="chat-input-row">
            <textarea
              className="chat-input"
              placeholder="Ask me to edit anything..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              rows={2}
            />
            <button
              className="chat-send-btn"
              onClick={handleSend}
              disabled={chatLoading || !input.trim()}
            >
              →
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Resume Preview with keyword highlighting ──────────────────────────────────
function ResumePreview({ resume, addedKeywords = [] }) {
  if (!resume) return <p className="text-muted">No resume generated yet.</p>;

  // Highlight injected keywords in any text
  function highlight(text) {
    if (!text || addedKeywords.length === 0) return text;
    const escaped = addedKeywords.map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
    const pattern = new RegExp(`(${escaped.join("|")})`, "gi");
    const parts = text.split(pattern);
    return parts.map((part, i) =>
      pattern.test(part) ? (
        <mark key={i} style={{
          background: "rgba(124,106,255,0.25)",
          color: "var(--accent2)",
          borderRadius: 3,
          padding: "0 2px",
          fontWeight: 600,
        }}>
          {part}
        </mark>
      ) : part
    );
  }

  return (
    <div style={{ fontSize: 14 }}>
      {/* Header */}
      <div style={{ marginBottom: 20, borderBottom: "1px solid var(--border)", paddingBottom: 16 }}>
        <h2 style={{ fontFamily: "var(--font-head)", fontSize: 22, fontWeight: 800 }}>
          {resume.name}
        </h2>
        <p className="text-muted text-sm" style={{ marginTop: 4 }}>
          {[resume.email, resume.phone, resume.location].filter(Boolean).join(" · ")}
        </p>
        {(resume.linkedin || resume.github) && (
          <p className="text-muted text-sm">
            {[resume.linkedin, resume.github, resume.portfolio].filter(Boolean).join(" · ")}
          </p>
        )}
      </div>

      {/* Summary */}
      {resume.summary && (
        <div className="structured-section">
          <h3>Summary</h3>
          <p className="text-muted" style={{ fontSize: 13, lineHeight: 1.6 }}>
            {highlight(resume.summary)}
          </p>
        </div>
      )}

      {/* Skills */}
      {resume.skills && (
        <div className="structured-section">
          <h3>Skills</h3>
          {resume.skills.technical?.length > 0 && (
            <p className="text-sm" style={{ marginBottom: 6 }}>
              <strong>Technical: </strong>
              <span className="text-muted">{highlight(resume.skills.technical.join(", "))}</span>
            </p>
          )}
          {resume.skills.tools?.length > 0 && (
            <p className="text-sm" style={{ marginBottom: 6 }}>
              <strong>Tools: </strong>
              <span className="text-muted">{highlight(resume.skills.tools.join(", "))}</span>
            </p>
          )}
          {resume.skills.soft?.length > 0 && (
            <p className="text-sm">
              <strong>Soft: </strong>
              <span className="text-muted">{resume.skills.soft.join(", ")}</span>
            </p>
          )}
        </div>
      )}

      {/* Experience */}
      {resume.experience?.length > 0 && (
        <div className="structured-section">
          <h3>Experience</h3>
          {resume.experience.map((exp, i) => (
            <div key={i} className="exp-item">
              <div className="flex justify-between">
                <span className="exp-title">{exp.title}</span>
                <span className="text-muted text-sm">{exp.start_date} – {exp.end_date}</span>
              </div>
              <p className="exp-meta">{exp.company} · {exp.location}</p>
              {exp.bullets?.map((b, j) => (
                <p key={j} className="exp-bullet">{highlight(b)}</p>
              ))}
            </div>
          ))}
        </div>
      )}

      {/* Projects */}
      {resume.projects?.length > 0 && (
        <div className="structured-section">
          <h3>Projects</h3>
          {resume.projects.map((proj, i) => (
            <div key={i} className="exp-item">
              <div className="flex justify-between">
                <span className="exp-title">{proj.name}</span>
                {proj.link && (
                  <a href={proj.link} target="_blank" rel="noreferrer"
                    className="text-sm" style={{ color: "var(--accent2)" }}>
                    Link ↗
                  </a>
                )}
              </div>
              <p className="text-muted text-sm" style={{ marginBottom: 4 }}>
                {highlight(proj.tech_stack?.join(", "))}
              </p>
              {proj.bullets?.map((b, j) => (
                <p key={j} className="exp-bullet">{highlight(b)}</p>
              ))}
            </div>
          ))}
        </div>
      )}

      {/* Education */}
      {resume.education?.length > 0 && (
        <div className="structured-section">
          <h3>Education</h3>
          {resume.education.map((edu, i) => (
            <div key={i} className="exp-item">
              <div className="flex justify-between">
                <span className="exp-title">{edu.degree}</span>
                <span className="text-muted text-sm">{edu.graduation_year}</span>
              </div>
              <p className="exp-meta">{edu.institution}</p>
              {edu.gpa && <p className="text-muted text-sm">GPA: {edu.gpa}</p>}
            </div>
          ))}
        </div>
      )}

      {/* Certifications */}
      {resume.certifications?.length > 0 && (
        <div className="structured-section">
          <h3>Certifications</h3>
          {resume.certifications.map((c, i) => (
            <p key={i} className="text-sm text-muted">
              {c.name} — {c.issuer} ({c.year})
            </p>
          ))}
        </div>
      )}
    </div>
  );
}
